templates.body:
{
  "telemetry": { "diagnostics": false, "metrics": false },
  "auto_update": false,
  "agent": {
    "commit_message_model": { "provider": "streamscope", "model": "{{model_slot_fast}}" },
    "thread_summary_model": { "provider": "streamscope", "model": "{{model_slot_fast}}" }
  },
  "language_models": {
    "openai_compatible": {
      "streamscope": {
        "api_url": "{{base_url}}",
        "available_models": [
{{#each routes}}          { "name": "{{model_alias}}", "display_name": "{{model_alias}}", "max_tokens": {{#if context_window}}{{context_window}}{{else}}128000{{/if}}{{#if supports_function_calling}}, "capabilities": { "tools": true{{#if supports_vision}}, "images": true{{/if}} }{{else}}{{#if supports_vision}}, "capabilities": { "images": true }{{/if}}{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}        ]
      }
    }
  }
}
